mapper.select:
select r.*,u.user_name as userName,u.phone,u.avatar,u.sex,m.room_name as roomName,m.room_no as roomNo
from room_user r
left join tb_user u on u.user_id=r.user_id
left join room m on m.room_id=r.room_id
where 1=1

    and u.user_id=#{userId}


    and r.room_id=#{roomId}


    and u.phone like concat('%',#{phone},'%')


    and m.room_id=#{roomId}


    and r.status=#{status}


    and r.is_seat=#{isSeat}


    and m.room_name like concat('%',#{roomName},'%')


    and u.user_name like concat('%',#{userName},'%')

order by r.create_time desc
